  const BANDO_COSTS={'BANDÔ CONJUGADO':106.60,'BANDÔ FLAT':73.74,'BANDÔ FLAT REVESTIDO':97.92,'BANDÔ BOX 70':83.04,'BANDÔ BOX 90':97.92,'BANDÔ BOX GRANDE':205.14,'BANDÔ SEMI-BOX GRANDE':143.58,'BARRA NIVELADORA':10.56};
